<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class ProductAd extends Model {protected $fillable=['farmer_id','product_id','title','description','image_path','image_url','original_price','discount_price','status','sort_order','admin_note','removal_requested_at']; protected function casts():array{return ['original_price'=>'decimal:2','discount_price'=>'decimal:2','removal_requested_at'=>'datetime'];} public function getDisplayImageAttribute():string {if($this->image_path)return \Illuminate\Support\Str::startsWith($this->image_path,['http://','https://']) ? $this->image_path : asset('storage/'.$this->image_path);if($this->image_url)return $this->image_url;if($this->product?->image)return \Illuminate\Support\Str::startsWith($this->product->image,['http://','https://']) ? $this->product->image : asset('storage/'.$this->product->image);return 'https://placehold.co/800x420?text=Farm+Product';} public function farmer():BelongsTo{return $this->belongsTo(User::class,'farmer_id');} public function product():BelongsTo{return $this->belongsTo(Product::class);}}